import math

def check_condition(n):
    """
    Checks if for all positive integers k coprime to n, k^2 - 1 is a multiple of n.
    We only need to check k in the range 1 <= k < n.
    """
    if n < 2:
        return False # Condition requires n >= 2

    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check if k^2 - 1 is a multiple of n
            if (k*k - 1) % n != 0:
                return False
    return True

# Check for n ranging from 2 up to 20
results = {}
for n in range(2, 21):
    results[n] = check_condition(n)

# Print the results
print("N | Passes Condition")
print("-" * 25)
for n in range(2, 21):
    status = "YES" if results[n] else "NO"
    print(f"{n:2} | {status}")

print("\nList of passing Ns:", [n for n, passes in results.items() if passes])

import math

def check_condition(n):
    """
    Checks if k^2 === 1 (mod n) for all k coprime to n.
    """
    if n < 2:
        return False

    # We only need to check k from 1 to n-1
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            if (k * k) % n != 1:
                return False
    return True

solutions = []
for n in range(2, 31):
    if check_condition(n):
        solutions.append(n)

print("Solutions found for n up to 30:", solutions)
